import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"漸","description":"周易集解 - 漸","frontmatter":{"title":"漸","description":"周易集解 - 漸"},"headers":[],"relativePath":"zh/classics/jijie/053.md","filePath":"zh/classics/jijie/053.md"}'),l={name:"zh/classics/jijie/053.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="漸" tabindex="-1">漸 <a class="header-anchor" href="#漸" aria-label="Permalink to “漸”">​</a></h1><h2 id="漸-1" tabindex="-1">漸 <a class="header-anchor" href="#漸-1" aria-label="Permalink to “漸”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>漸，女歸吉，利貞。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：物不可以終止，故受之以漸。漸者，進也。</p><p>崔憬曰：終止雖獲敦艮，時行須漸進行，故曰｢物不可終止，故受之以漸。漸者，進也｣。</p><p>虞翻曰：否三之四。女，謂四。歸，嫁也。坤三之四承五，進得位，往有功。反成歸妹，兌女歸吉。初上失位。故利貞，可以正邦也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：漸之進也，女歸吉也。進得位，往有功也。進以正，可以正邦也。其位剛得中也。止而巽，動不窮也。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>虞翻曰：三進四，得位。陰陽體正，故吉也。</p><p>虞翻曰：功謂五，四進承五，故往有功。巽為進也。</p><p>虞翻曰：謂初已變，為家人。四進已正，而上不正。三動成坤，為邦。上來反三。故｢進以正，可以正邦｣。其位剛得中，與家人道正同義。三在外體之中，故稱得中。《乾．文言》曰：中不在人，謂三也。此可謂上變既濟定者也。</p><p>虞翻曰：止，艮也。三變震為動。上之三據坤。動震成坎，坎為通。故動不窮。往來不窮謂之通。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：山上有木，漸。君子居賢德善俗。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：君子謂否乾。乾為賢德。坤陰小人柔弱，為俗。乾四之坤為艮，為居。以陽善陰。故以居賢德善俗也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，鴻漸於乾，小子厲，有言，無咎。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：鴻，大雁也。離五，鴻。漸，進也。小水從山流下稱乾。艮為山，為小徑。坎水流下山。故鴻漸於乾也。艮為小子。初失位，故厲。變得正。三動受上成震，震為言。故｢小子厲，有言，無咎｣也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：小子之厲，義無咎也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：動而得正，故義無咎也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，鴻漸於磐，飲食衎衎，吉。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：艮為山石。坎為聚，聚石稱磐。初已之正，體噬嗑食，坎水陽物，竝在頤中，故飲食衎衎。得正應五，故吉。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：飲食衎衎，不素飽也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：素，空也。承三應五，故不素飽。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，鴻漸於陸，夫徵不復，婦孕不育，凶。利用禦寇。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：高平稱陸。謂初已變，坎水為平。三動之坤，故鴻漸於陸。</p><p>虞翻曰：謂初已之正。三動成震。震為徵、為夫而體復，象坎陽死坤中，坎象不見。故夫徵不復也。</p><p>虞翻曰：孕，妊娠也。育，生也。巽為婦，離為孕，三動成坤，離毀失位，故婦孕不育凶。</p><p>虞翻曰：御，當也。坤為用，巽為高，艮為山，離為戈兵甲胄，坎為寇。自上御下，三動坤順，坎象不見。故利用禦寇。順相保，保，大也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：夫徵不復，離群醜也。婦孕不育，失其道也。利用禦寇，順相保也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：坤三爻為醜，物三稱群也。</p><p>虞翻曰：三動離毀，陽隕坤中，故失其道也。</p><p>虞翻曰：三動坤順，坎象不見，故以順相保也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，鴻漸於木，或得其桷，無咎。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：巽為木。桷，椽也。方者謂之桷。巽為交，為長木，艮為小木，坎為脊，離為麗。小木麗長木，巽繩束之，象脊之形，椽桷象也，故或得其桷。得位順五，故無咎。四已承五，又顧得三，故或得其桷也矣。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：或得其桷，順以巽也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：坤為順，以巽順五。</p><p>案：四居巽木，爻陰位正，直桷之象也。自二至五，體有離坎。離為飛鳥而居坎水，鴻之象也。鴻隨陽鳥，喻女從夫。卦明漸義，爻皆稱焉。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，鴻漸於陵，婦三歲不孕，終莫之勝，吉。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：陵，丘。婦，謂四也，三動受上時，而四體半艮山，故稱陵。巽為婦，離為孕，坎為歲，三動離壞，故婦三歲不孕。</p><p>虞翻曰：莫，無。勝，陵也。得正居中，故莫之勝吉。上終變之三，成既濟定。坎為心，故《象》曰｢得所願也｣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：終莫之勝吉，得所願也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：上之三，既濟定，故得所願也。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，鴻漸於陸，其羽可用為儀，吉。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：陸，謂三也。三坎為平，變而成坤，故稱陸也。</p><p>虞翻曰：謂三變受成既濟，與《家人．彖》同義。上之二得正，離為鳥，故其羽可用為儀吉。三動失位，坎為亂，乾四止坤，《象》曰｢不可亂｣，《彖》曰｢進以正邦｣，為此爻發也。三已得位，又變受上權也。孔子曰：可與適道，未可與權，宜無怪焉。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：其羽可用為儀吉，不可亂也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：坤為亂，上來正坤。六爻得位，成既濟定，故不可亂也。乾寶曰：處漸高位，斷漸之進。順艮之言，謹巽之全，履坎之通，據離之耀。婦德既終，母教又明。有德而可受，有儀而可象。故曰｢其羽可以為儀，不可亂也。｣</p>',75)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
